function slugify(title) {
  return title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

module.exports = { slugify };

import test from 'node:test';
import assert from 'node:assert';
import { slugify } from '../src/slug.js';

test('slugify basic case', () => {
  assert.strictEqual(slugify('Hello World!'), 'hello-world');
});

test('slugify with multiple spaces', () => {
  assert.strictEqual(slugify('Hello   World'), 'hello-world');
});

test('slugify with special characters', () => {
  assert.strictEqual(slugify('Hello-World!@#'), 'hello-world');
});

test('slugify with leading/trailing non-alphanumerics', () => {
  assert.strictEqual(slugify('!!!Hello World!!!'), 'hello-world');
});

test('slugify already lowercase', () => {
  assert.strictEqual(slugify('hello-world'), 'hello-world');
});

test('slugify with numbers', () => {
  assert.strictEqual(slugify('Hello World 123'), 'hello-world-123');
});

test('slugify with underscores', () => {
  assert.strictEqual(slugify('hello_world_test'), 'hello-world-test');
});

test('slugify empty string', () => {
  assert.strictEqual(slugify(''), '');
});

test('slugify only special characters', () => {
  assert.strictEqual(slugify('!!!'), '');
});

test('slugify single word', () => {
  assert.strictEqual(slugify('Hello'), 'hello');
});

